/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

extern s32 gSaveSlotCount;

/* Returns index (16-bit) if it is a valid save slot, otherwise wraps it by subtracting 4 from the slot count. */ s32 wrapSaveSlotIndex(s32 index) {
    s32 slot;
    s32 wrapDelta;

    slot = index & 0xFFFF;
    if (slot < gSaveSlotCount) {
        return slot;
    }
    wrapDelta = gSaveSlotCount + 0xFFFC;
    return (index + wrapDelta) & 0xFFFF;
}
